// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":134,"question":"ما حكم الرشوة إذا كان حقِّي المعلوم أو تعويضي المُقدر لي لن يتم إلَّا عن طريقها؟","title":"هل يجوز دفع الرشوة لاستعادة الحقوق؟","answer":"الجواب: لا تجوز الرشوة؛ لأن هذا معناه إعانة على الباطل، وإعانة على تضييع الحقوق، وظلم الناس، يقول الرسولُ ﷺ: لعن الله الرَّاشي والمُرتشي، وفي روايةٍ: والرائش الواسطة بينهما أيضًا. فلا يجوز التعاون على الباطل والإثم، بل اطلب حقَّك من الطريق الشرعي، وإذا كان أحدٌ يقف في طريقك فارفع أمره، وافضحه على تساهله، ولا تُعنه على معاصي الله بالرشوة.","link":"https://binbaz.org.sa/fatwas/3662/هل-يجوز-دفع-الرشوة-لاستعادة-الحقوق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0123.mp3","categories":["الكسب المحرم"]},{"id":150,"question":"رجلٌ يقول: أنا من الموظفين في مكة المكرمة، وعندما يأتي إليَّ الحجاج يُريدون أن أستأجر بيتًا، فأتفق أنا وصاحب البيت على أن يُؤجرهم مثلًا بألفين، ولي منه ثلاثمئة ريـال، فهل هذه رشوة؟","title":"حكم السمسرة لمن يعمل في خدمة الحجيج؟","answer":"الجواب: لا بدّ أن يُعلمهم إذا اتفق هو وإياه، فلا يجوز إلا أن يُعلمهم؛ لأن هذه من جنس الرشوة، لأنه يُخبرهم أنه بألفين وما هو بألفين، بل بألف وسبعمئة، فهذا ما يجوز، هذا من الرشوة، فإذا كان يريد الحلال فليقل لهم: إني اتفقتُ معه على أنها بألفين، وأن لي ثلاثمئة إذا كنتم تسمحون بذلك، وإلا فليس له إلا ألف وسبعمئة، وهو وافق على الثلاثمئة لي إن سمحتم بها، وإلا تركتها، أو ما أشبه ذلك من الكلام، يعني: لا بدّ أن يُبين لهم، وإلا فهو خيانة.","link":"https://binbaz.org.sa/fatwas/3687/حكم-السمسرة-لمن-يعمل-في-خدمة-الحجيج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0143.mp3","categories":["الكسب المحرم"]},{"id":160,"question":"أحيانًا يضطر الإنسانُ لدفع رشوةٍ في سبيل الحصول على حقٍّ له لا يمكن الحصول عليه إلا بهذه الطريقة؟","title":"حكم دفع الرشوة للحصول على الحقوق","answer":"الجواب: هذا فيه تفصيل: إذا كان حقُّه يضيع ولا يتيسَّر له أخذ حقّه إلا بمالٍ يبذله لشخصٍ يتوصل به إلى حقِّه، ولا يضرُّ غيره إذا بذل هذا المال، بل إنسانٌ أخذ مالك وضرَّك، وله مثلًا صاحبٌ أو له خادمٌ يستطيع أن يشفع لك، فتُعطيه مالًا ليشفع لك وليتسبب في إخراج مالك من هذا الظالم؛ فلا حرج في ذلك.\nمثل: بدوي أو حضري أخذ مالك -أخذ غنمك، أخذ سيارتك- فتُعطي خادمه أو تُعطي أخاه أو قريبه أو شيخ القبيلة شيئًا حتى يُخلصك من هذا، وإن كان لا يحلّ لشيخ القبيلة ونحوه، لكن إذا لم يتيسر إلَّا بهذا فأنت ما تعديتَ على أحدٍ، إنما طلبت مالك وحقَّك الذي ظُلمتَ فيه.\nومثل: قُطَّاع الطريق أخذوا مالك، فتُعطيهم شيئًا من مالك حتى يردُّوا عليك بعضَه، أو السارق أخذ منك ألفًا فتقول: أعطني خمسمئة، ولك خمسمئة، هو لا يحلُّ له، لكن لا بأس أن تُعطيه بعض الحقِّ حتى يردَّ عليك بعض الحق الثاني.","link":"https://binbaz.org.sa/fatwas/3698/حكم-دفع-الرشوة-للحصول-على-الحقوق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0154.mp3","categories":["الكسب المحرم"]},{"id":301,"question":"فضيلة الشيخ، ما الحكم الشَّرعي فيمَن دفع الرشوة حتى يُحقّ الحقَّ ويُبطل الباطل؟ مع العلم أنه إذا لم تُدفع الرشوة فسوف يحقّ الباطل -لا سمح الله.","title":"حكم دفع الرشوة لإحقاق الحق وإبطال الباطل","answer":"الجواب: الشيخ: بسم الله الرحمن الرحيم، الحمد لله، وصلَّى الله وسلَّم على رسول الله، وعلى آله وأصحابه ومَن اهتدى بهُداه.\nأما بعد: فقد حرَّم الله عزَّ وجل الرشوة، ولعن الراشي والمُرتشي على لسان نبيه محمد عليه الصلاة والسلام، فالرشوة معناها: أن يُقدّم المال ليميل المُعْطَى عن الحقِّ إلى الباطل، أو ليُعطي الراشي غير حقِّه، أو ليُقدمه على غيره، أو لشبه ذلك من الباطل، هذه هي الرشوة، فلا يجوز تقديمها لأحدٍ من الناس، بل هي من كبائر الذنوب، ومن أكل أموال الناس بالباطل، ومن أسباب فساد المُجتمع وضياع الحق.\nولو ادَّعى صاحبُها أنه يُريد أن يُحقَّ الحقَّ فليس له أن يُقدّم الرشوة، بل يجب عليه أن يمتنع من ذلك، وأن يطلب حقَّه بالطرق الشرعية التي شرعها الله لعباده وأباحها لهم.\nولو فُتح هذا الباب لكان كل واحدٍ يدَّعي أنه طلب الحقَّ، وأنه إنما قدَّمها لحقٍّ، لا، الرشوة مال سُحتٍ مُحرَّم على الباذل والمبذول له، وعلى الموظف.\nوعلى القائم على الأعمال الذي يُريد رشوته -عليه أن يتَّقي الله، وأن يلتزم بالحقِّ، وإذا عُلم منه أنه يميل عن ذلك؛ فالواجب على مَن عرف ذلك أن يشهد عليه بعمله السيئ حتى يلقى جزاءه بالتأديب والفصل وغير ذلك.","link":"https://binbaz.org.sa/fatwas/4303/حكم-دفع-الرشوة-لاحقاق-الحق-وابطال-الباطل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0350.mp3","categories":["الكسب المحرم"]},{"id":372,"question":"هل يجوز للمسلم أن يُؤجِّر بيته للكافر، سواء كان كتابيًّا أو غير كتابي؟ وكيف يستطيع أن يُعامله إذا كان.....؟","title":"حكم وكيفية المعاملات مع غير المسلمين","answer":"الجواب: أما في هذه الجزيرة فلا؛ لأنَّ الله جلَّ وعلا حرَّم علينا إباحة هذه الجزيرة لهم، وأوصى النبي ﷺ بإخراج المشركين من هذه الجزيرة، كما ثبت في \"الصحيح\" أن النبي أوصى بإخراجهم من الجزيرة وقال: لا ألفين اليهود والنَّصارى في جزيرة العرب حتى لا أدع إلا مسلمًا، فهذه الجزيرة يجب أن تكون خالصةً للمؤمنين، ليس فيها أخلاطٌ، فهي مهد الإسلام، ومنبع الإسلام، وبلاد الإسلام التي خرج منها وانتشر منها، وقد قرر النبيُّ ﷺ أن يكون فيها دينٌ واحدٌ وهو الإسلام، وألا يكون فيها دينان.\nفلا يجوز للمسلم أن يتساهل في وجود المشركين فيها بالتأجير عليه، أو جلبه إلى العمل هنا، أو نحو ذلك، فلا يُستجلب للعمل: لا سائقًا، ولا عاملًا، ولا غير ذلك، ولا يُؤجّر عليه ما يُؤهله ويُرغبه في البقاء: من مزرعةٍ أو بيتٍ أو دكانٍ أو غير ذلك، اللهم إلا أن تضطر الدولةُ إلى شيءٍ من ذلك: كطبيبٍ مهمٍّ، أو ما أشبه ذلك للضَّرورة، كما أقرَّ النبيُّ ﷺ اليهود في خيبر للعمل؛ لما كان المسلمون مشغولين بالجهاد.\nفالحاصل أنَّ الواجب إبعادهم عن هذه الجزيرة، وألا يتساهل معهم فيها، أما في غير الجزيرة كالشام والعراق ومصر وغير ذلك فلا بأس أن يُؤجّرهم؛ لأنه يجوز لهم السكن، إلا إذا كان يُؤجّر على قومٍ يفعلون الباطل ويُعينهم على الباطل: كتأجير دارٍ على مَن يبيع الخمر، أو مَن يُحارب المسلمين، أو ما أشبه، لا، فلا يُؤجر عليهم ولو كان في بلاد الكفر، أما في بلاد الجزيرة العربية فلا، لا يُؤجر مطلقًا، لا يجوز التأجير عليهم مطلقًا؛ لأنَّ بقاءهم هنا ممنوع.","link":"https://binbaz.org.sa/fatwas/4629/حكم-وكيفية-المعاملات-مع-غير-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0427.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":419,"question":"هل يجوز تأجير المحلات على أصحاب المعاصي: كحالق اللحية، وتارك الصلاة، أم أنَّ هناك تفصيلًا؟","title":"حكم تأجير المحلات لأصحاب المعاصي","answer":"الجواب: أما تأجيرها على الكفرة فلا، تأجيرها على النصارى أو على مَن يُعرف بالشرك -كالبوذية وأشباههم- فلا. أما العاصي فيجوز التأجير عليه، لكن إذا التمس الطيبين أحسن. أما تأجيرها على مَن يُقيم فيها المعاصي: مَن يجعلها موضعًا لحلاقة اللِّحَى، أو موضعًا لعمل الربا، أو موضعًا لبيع الخمور والمخدرات، هذا لا يجوز؛ لأنه إعانةٌ لهم على الإثم والعدوان.","link":"https://binbaz.org.sa/fatwas/4843/حكم-تاجير-المحلات-لاصحاب-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0477.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":447,"question":"إذا اتفق صاحب التاكسي مع الفندق أو أحد المطاعم بأنه إذا أتى بزبائن يعطيه مقابل الزبائن هؤلاء، فيه شيء؟","title":"ما حكم أخذ أجرة مقابل جلب زبائن؟","answer":"الجواب: ما في شيء، بس عليه أن يتقي الله، لا يحابي، وعلى صاحب التاكسي لا يحابي، لا يجيبهم للفندق الغالي ويخلي الفندق اللي مناسبهم ويغرّهم ويخدعهم حتى يأخذ الفلوس، عليه أن يتقي الله.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6170/ما-حكم-اخذ-اجرة-مقابل-جلب-زباىن","audio":"https://files.zadapps.info/binbaz.org.sa/SEK005.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":452,"question":"إذا كان الموظف لا يعطيني حقي إلا بالرشوة؟","title":"ما حكم الرشوة لموظفٍ لا ينجز إلا بها؟","answer":"الجواب: افضحه وارفع أمره للمسؤول أن هذا ما يعطيني حقي إلا بالرشوة، ولا تتساهل معه.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6175/ما-حكم-الرشوة-لموظف-لا-ينجز-الا-بها","audio":"https://files.zadapps.info/binbaz.org.sa/reshwa010.mp3","categories":["الكسب المحرم","أحكام الموظفين"]},{"id":453,"question":"أغلب الموظفين لا يعطيك هذا الحق حتى تدفع مقابلها رشوة، فمثل هذا ماذا على الإنسان أن يصنع؟","title":"ما حكم دفع الرشوة من أجل أخذ الحق؟","answer":"الجواب: ج: إذا كان سيضيع الحق فهذه ضرورة، والإثم عليه، إذا كان ضرورة، الشرط الضرورة.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6176/ما-حكم-دفع-الرشوة-من-اجل-اخذ-الحق","audio":"https://files.zadapps.info/binbaz.org.sa/reshwaa011.mp3","categories":["الكسب المحرم"]},{"id":454,"question":"إحدى النساء خصصت أن تأخذ مبلغًا قدره خمسة آلاف ريال مقابل التعيين في المنطقة التي تحتاجها؟","title":"حكم تقاضي الموظف أموالًا لتقديم خدمات","answer":"الجواب: هذا من الشفاعة، وهذا من الاعتداء، وهذا من المُحَرَّم، الواجب عليها أن تعمل بمقتضى التعليمات بدون رشوة.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6178/حكم-تقاضي-الموظف-اموالا-لتقديم-خدمات","audio":"https://files.zadapps.info/binbaz.org.sa/sho3'l013.mp3","categories":["الكسب المحرم","أحكام الموظفين"]},{"id":462,"question":"صاحب العقار يشترط عقد سنة لإيجار سنة، فبعد مضي ستة أشهر لو أخلى المستأجر المنزل هل يرجع إليه النصف الباقي؟","title":"هل العقد بين المؤجر والمستأجر ملزم لهما؟","answer":"الجواب: لا ما يرجع؛ لأن العقد لازم إما يكملون وإلا يؤجره على غيره.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6187/هل-العقد-بين-الموجر-والمستاجر-ملزم-لهما","audio":"https://files.zadapps.info/binbaz.org.sa/3akar022.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":464,"question":"بعض الأشخاص يكون يستقدم عمالاً ويقول: آخر الشهر تسلمني -مثلاً- ألف ريال، ويُطْلِقهم لكي يعملوا؟","title":"ما حكم استقدام عمال وإطلاقهم مقابل أموال؟","answer":"الجواب: ما يصح هذا، لا يجوز، هذا أخذ مال بغير حق، ولا يجوز استقدامه إلا لمصلحته مثل ما صدر من الدولة، صدر من هيئة كبار العلماء، يكون الاستقدام على قدر ما سمحت الدولة؛ لأن هذا من باب المصالح العامة.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6189/ما-حكم-استقدام-عمال-واطلاقهم-مقابل-اموال","audio":"https://files.zadapps.info/binbaz.org.sa/estkdam024.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":524,"question":"الأموال التي يأخذنها من يضربن بالدف حلال أو حرام؟","title":"حكم الأجرة مقابل ضرب الدف بالأعراس","answer":"الجواب: لا حرج إن شاء الله؛ لأن الدف جائز في النكاح.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6355/حكم-الاجرة-مقابل-ضرب-الدف-بالاعراس","audio":"https://files.zadapps.info/binbaz.org.sa/maram090 - 04 - .mp3","categories":["الكسب المحرم","الإجارة"]},{"id":750,"question":"إنني رجلٌ فطين والحمد لله، وأطلع غالبًا على مُروجي المُخدرات، إلا أني بعد أن علم بعض زملائي بأنني أكتشف هذه الطريقة السيئة أساؤوا إليَّ بنظرتهم: أنني جاسوس، أو أنني موسوس، أو غير ذلك، وتُدفع لي المُكافآت من الإجازة والنقود، فهل عملي هذا يُخالف الحياء أو الشَّرع؟","title":"ما حكم العمل في مكافحة المخدرات؟","answer":"الجواب: هذا من باب التعاون على البر والتقوى، من باب التعاون على الخير، الإنسان كونه يعتني بأهل المخدرات والمسكرات والذين يضرون الناس، فيرفع عنهم ما يتعاطونه ويُشيعونه بين الناس؛ هذا من باب التعاون على البر والتقوى، ومحاربة أهل الشرور، فليس عليه حرجٌ في ذلك إذا أخبر عمَّن يبيع المخدرات أو يستوردها ويُروجها؛ لأن هذا يضرُّ الناس ضررًا عظيمًا، فالذي يُساعد على إبعاده وعلى القضاء عليه وعلى منعه من هذا البلاء مأجورٌ، ولو كره بعضُ الناس، ولو أساء إليه بعضُ الناس؛ لأنه ساعٍ في إصلاح الأمة وسلمها من هذا الداء العظيم، والشر الوبيل.","link":"https://binbaz.org.sa/fatwas/20644/ما-حكم-العمل-في-مكافحة-المخدرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0567حكم العمل في محافحة المخدرات ابن باز فتاوى المحاضرات.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":772,"question":"ما رأيكم في رجلٍ أتى على بئرٍ أوقف في سبيل الله، فجعل عليها ماطورًا يخرج به الماء، ويقوم بتوصيل الماء إلى مَن يريده في مكانه، ولكنه لا يُعطي أحدًا الماء حتى يتقاضى منه بعضَ الأجر على قدر ما يُريد من الماء؟","title":"حكم مَن يُوصل ماء بئر موقوفة مقابل أجر","answer":"الجواب: إذا كان ولاةُ الأمر قد أقرُّوه على هذا، أو كان في البلد وافقوا على أمثاله، ولو كان ما فيها ولاة أمرٍ، وافق مع أهل بلدٍ والقرية على هذا؛ لأنها متعطلة، فجاء الله به وأصلحها، ووكلوا عليه الماطور، ونفعهم؛ لا بأس بذلك. أما إن كان ظالمًا في ذلك: بأن يوجد مَن يريد إيصال الماء بغير ثمنٍ وبغير تعبٍ وهو منعه من ذلك، وفرض أمره هو حتى يأخذ من أموال الناس؛ هذا يُمنع. أما إذا كان عن تراضٍ بينه وبين أهل البلد، أو عن إحسانٍ منه؛ لأنها معطلة، فأحسن في ذلك، وأخذ الشيء اليسير والأجر اليسير على قدر تعبه، أو أنَّ ولاة الأمور عيَّنوه في هذا، ووافقوا عليه؛ فلا بأس بذلك.","link":"https://binbaz.org.sa/fatwas/20694/حكم-من-يوصل-ماء-بىر-موقوفة-مقابل-اجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0591ما رأيكم في رجل أتى على بئر موقوفه فيخرج منه الماء ويقوم بتوصيل الماء ويأخذ أجر على ذلك.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":912,"question":"كثر استقدام النَّصارى من العاملين بحجّة الخبرة أو الزراعة أو غير هذا، حتى أن البعض منهم عملوا بقرب حدود مكة، فما حكم هذا؟","title":"حكم استقدام النصارى بحجة الخبرة ونحوها","answer":"الجواب: استقدام الكفرة من المصائب العظيمة في هذه الجزيرة، والرسول ﷺ أوصى بإخراجهم من الجزيرة وقال: لا يجتمع فيها دينان، فهي مهبط الوحي، ومنبع الرسالة، فالواجب تطهيرها من الكفرة، إلا من عارضٍ: كالذي يقدم لبيع حاجات ميرة أو أشياء ثم يرجع، أو يقدم للاتِّصال بولي الأمر مُرْسَلًا من دولته، أو ما أشبه ذلك.\nأما استقدامهم للعمل فيها والإقامة فيها فهذا خطيرٌ، فظاهر الأدلة منعه، إلا من حاجةٍ يراها ولي الأمر خاصةً في مصلحة المسلمين: كطبيبٍ تدعو له الحاجة، أو عاملٍ تدعو له الحاجة لإصلاح سلاحٍ، أو غيره.\nولهذا استخدم النبيُّ ﷺ اليهود في خيبر للحاجة، ثم أجلاهم عمر، ولم يزل يقبل الرسل عليه الصلاة والسلام المرسلة من دولهم، فيأخذ معهم ويُعطي فيما قدموا إليه.\nأما استقدامهم على هذه الحال للخدمة: من سوّاقين، أو خدم، أو عمال، هذا لا يجوز، والواجب على ولاة الأمور -وفَّقهم الله- أن يحدّوا من هذا الأمر، وأن يجتهدوا في تخليصه وتقليله حسب الطاقة، وقد وعد خادمُ الحرمين بذلك -وفَّقه الله- ونسأل الله أن يُعين على التنفيذ.\nوالواجب على الأمة ألا تتساهل في هذا الأمر، وأن تكون عونًا لأهل الخير في هذا الأمر، كل إنسانٍ عنده شركة أو مصنع يجتهد في استقدام المسلمين، ولو كانوا أغلى، الله يبارك له ويُعينه، لكن المصيبة ضعف الإيمان، هذا يدَّعي أن المسلم غالٍ، وهذا يدَّعي أن المسلم يروح يُصلي ويُضيع بعض الوقت، وهذا من البلاء العظيم، نعوذ بالله.\nالواجب أنه يستقدم المسلمين، يكون نفعه في المسلم أو المسلمة، لا في الكفرة، وإذا كان في بلاد المسلمين مسلمون أو مسلمات استقدمهم، والمسلمون موجودون في مصر، في الشام، في العراق، في الهند، في باكستان، في أي مكانٍ، يتحرى وكيله، ويجتهد في استقدام الطيبين من المسلمين والطيبات عند الحاجة، حتى تكون الأموال في المسلمين لا في غيرهم، وحتى لا يُستقدم لهذه الجزيرة إلا المسلمون.\nهذا الواجب على مندوبي الشركات، وعلى الشركات أنفسها، وعلى المؤسسات، وعلى الدولة، وعلى كل أحدٍ، الواجب التواصي بهذا الأمر، والحرص والنصح لله ولعباده، وعدم إيثار الدنيا بالمقالات الفاسدة: أن هؤلاء أرخص، أو: هؤلاء أنصح، أو: هؤلاء كل وقته في العمل؛ كل هذا باطلٌ، المسلم أنصح وأطيب، فإذا أخلَّ المسلم فهو لضعف إيمانه، وضعف إسلامه، إذا كان إيمانه قويًّا سوف ينصح أكثر من الكافر، وسوف يقوم بالمهمة أكثر من الكافر، فلا يخلّ بالأمانة إلا من ضعف إسلامه، أو عدم إسلامه.","link":"https://binbaz.org.sa/fatwas/20947/حكم-استقدام-النصارى-بحجة-الخبرة-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0743حكم استقدام النصارى بحجة الخبرة والزراعة أو غير ذلك.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":1065,"question":"نرجو من سماحتكم بيان حكم مَن يأتي بالعمال من الخارج، ويُسرِّحهم في البلاد ليعملوا لحسابه، وفي مقابل ذلك يأخذ عليهم مبلغًا معلومًا، أو نسبةً من مكاسبهم، وهل هذا جائزٌ أم لا؟","title":"حكم الكفيل الذي يترك عماله مقابل مبلغ مالي","answer":"الجواب:\nهذه المسألة درسها مجلسُ هيئة كبار العلماء، وقرر فيها المنع، وأنه لا يجوز لأسبابٍ كثيرةٍ، منها: أنه يأخذ هذا في غير مقابل ما يأخذ، ومنها أنه سببٌ للفساد في الأرض، لا يهمه إلا هذا الذي يأخذ، وربما أتى بعمالٍ يضرُّون الناس من الكفرة والفسقة. فليس له أن يستقدم إلا على الطريق التي رسمتها الدولة، عليه أن يتحرى ما أقرَّته الدولة، وما رسمته الدولة، فيستقدم على ذلك الطريق؛ لأنَّ ذلك هو المباح من جهة الدولة، وعلى العبد السمع والطاعة، ولأنه الطريق إلى تخفيف الشرِّ، والسلامة من شرِّ المستَقْدَمين، وإلى أكل الحلال أيضًا.","link":"https://binbaz.org.sa/fatwas/21117/حكم-الكفيل-الذي-يترك-عماله-مقابل-مبلغ-مالي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0913ما حكم من يأتي بالعمال من الخارج ويسرحها في البلاد يعملون لحسابه وفي المقابل يأخذ عليها مبالغ؟.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":1328,"question":"حق الآدمي يلزم أنه يخبر أو يرسل مالاً لشخص يخشى من الإحراج منه، ألف ريال؟ هل يلزم أن يقول إنه أخذها وسرقها؟أو يرسل شخصًا يقول: من شخص مجهول؟","title":"حكم من أخذ ما ليس له وتحرَّج في إرجاعه","answer":"الجواب:\nيعطيه إياها إن أمكن، وإن ما أمكن وخاف من التَّبِعة يرسلها إليه من ثقة يقول: هذه لك من إنسان يرى أن لك حقًا عليه وهذا حقك عليه، ولا يبيّنه؛ حتى لا يقع شيء بينه وبينه.\nس: وإذا كان والده -أحسن الله إليك- قد أخذ منه؟\nج: صاحبه أو والده وإلا غيره، يرسلها مع ثقة ويسلمها له ولا يعلمه مَنْ، ويقول: هذا إنسان ذكر أن لك عليه حقًّا، وهذا حقكم عليه أرسلني به.","link":"https://binbaz.org.sa/fatwas/21419/حكم-من-اخذ-ما-ليس-له-وتحرج-في-ارجاعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من أخذ ما ليس له وأراد إرجاعه وخشي الحرج.mp3","categories":["الكسب المحرم"]},{"id":1417,"question":"ما رأي سماحتكم من أن رجلًا لديه معاملة في دائرة حكومية وعطَّل هذا الشخص هذه المعاملة مدة طويلة، فهل يجوز أن يدفع للموظف الذي أخَّر المعاملة مبلغًا من المال لتخليص هذه المعاملة؟ علمًا بأنه ليس لها ضرر بالآخرين، وهل تعتبر هذه رشوة؟","title":"ما حكم دفع الرشوة لتخليص معاملة؟","answer":"الجواب:\nلا يجوز إعطاء الموظف شيئًا؛ لأن إعطاء الموظف شيئًا معناه التَّسَبُّب في تعطيل معاملات الآخرين وتعجيل معاملة صاحب الرشوة، لا يعطوهم، لكن يُلاحقون ويُراجعون حتى يعملوا ما يلزم، أما البخششة لبعض الموظفين ما تصلح.\nس: ما يبلغ عنهم؟\nج: إذا بلغ عنهم جزاه الله خيرًا، لكن أخاف إن بلغ عنهم يزيدون شرًّا.","link":"https://binbaz.org.sa/fatwas/21512/ما-حكم-دفع-الرشوة-لتخليص-معاملة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم دفع الرشوة لتخليص معاملة.mp3","categories":["الكسب المحرم"]},{"id":1452,"question":"بعض البلدان الآن إذا سافر الإنسانُ يأتي عند الجوازات أو الجمرك فيقول الموظف: لا تمشي إلا إذا أعطيتني قروشًا، فما حكمه؟","title":"حكم إعطاء الرشوة لموظف الجوازات","answer":"الجواب:\nما يجوز له أن يُعْطَى، هذه رشوة، فلا يُعْطَى، ويُشتكى إلى مرجعه.","link":"https://binbaz.org.sa/fatwas/21549/حكم-اعطاء-الرشوة-لموظف-الجوازات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم إعطاء الرشوة لموظف الجوازات.mp3","categories":["الكسب المحرم"]},{"id":1517,"question":"إنسانٌ عنده عمارة، ويؤجر بعض المحلات للذين يبيعون الدش وأجهزة التليفونات والتلفاز، فما حكم هذا؟","title":"حكم تأجير المحلات لمن يبيع \"الدِّشّ\" ونحوه","answer":"الجواب:\nيُؤجِّر على غيرهم أحوْط، وإلا فهذه مخلوطة لا بأس، أقول: مخلوطة فيها الخير والشر.\nس: فيها دشّ؟\nج: لا يجوز بيع الدش.\nس: هو أجَّرها عليهم؟\nج: لا يؤجر على الذين يبيعون الدُّشوش.","link":"https://binbaz.org.sa/fatwas/21616/حكم-تاجير-المحلات-لمن-يبيع-الدش-ونحوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تأجير المحلات لمن يبيعون الدش وأجهزة التليفونات والتلفاز.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":2158,"question":"بالنسبة لسعي السِّمسار: هل من حقِّ السمسار أم من حقِّ المالك؟","title":"هل أجرة السمسار حقِّ له أم للمالك؟","answer":"الجواب:\nهذا على مَن شُرِطَ عليه: إن كان شُرِطَ على البائع فعلى البائع، وإن كان شُرِطَ على المشتري فعلى المشتري، فالسمسار دلَّالٌ.\nس: هذا الأمر مفروغٌ منه، لكن محلّ السؤال هنا أن بعض السَّماسرة يبيعون للمالك السّلعة بثمنٍ جيدٍ ومكسبٍ ممتازٍ وفوق هذا فإنَّ هذا المالك الغني يشترط نصفَ السّعي له؟\nج: إذا ما أعطاه إلا النصف فالمسلمون على شروطهم، فإذا كان لهذا السعي جنيه ونصف على المئة، فقال: ما أُعطيه إلا ريالًا وربعًا، فلا بأس، فالمسلمون على شروطهم؛ لأنه قد تكون له أموال كثيرة فنصف السّعي ينفعه.\nس: لا، المشتري يدفع السعي كاملًا، ولكن المالك...؟\nج: المسلمون على شروطهم، فإذا شرطوا ذلك فلا بأس.","link":"https://binbaz.org.sa/fatwas/22279/هل-اجرة-السمسار-حق-له-ام-للمالك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سعي السمسار هل من حقِّ السمسار أم من حقِّ المالك.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":2202,"question":"صاحب محلٍّ عنده عاملٌ يُشَغّله، ويقول له: راتبك عبارة عن نسبة من الربح، فإذا ربحت مثلًا 5% أو 10% يكون راتبك نسبةً من هذا الربح، فلو ربح مثلًا ألف ريـال تكون له من الألف مئةُ ريـال؟","title":"حكم إعطاء الأجير أجرته بنسبة من الربح","answer":"الجواب:\nإذا كان عنده عامل بجزء مشاع، فيضع عنده السلعة فيبيعها بنصف الربح أو بثلث الربح فلا بأس؛ لأنَّه معروفٌ، ما هو مجهولٌ.","link":"https://binbaz.org.sa/fatwas/22325/حكم-اعطاء-الاجير-اجرته-بنسبة-من-الربح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إعطاء الأجير أجرته بالنسبة من الربح.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":2226,"question":"تأجير المحلات على العُمَّال؟","title":"حكم تأجير المحلات للعاملين فيها؟","answer":"الجواب:\nيبيع فيه ويشتري أو يسكنه؟\nس: لا، للبيع والشراء، للتجارة.\nج: لا بأس، والأجرة ما هي؟\nس: الاتفاق أن يكون بينهم راتبٌ، لكن هو يُسقط الراتب.\nج: المقصود أن يترك في الدّكان وكيلًا يبيع ويشتري عنه بالوكالة، لا بأس.\nس: العامل يُعطي الكفيلَ كل شهر ألفي ريـال، والبضاعة من العامل، والبيع والشراء كله من العامل؟\nج: هذه أجرة عن المحل، والعامل هو الذي يبيع ويشتري.\nس: والبضاعة من العامل؟!\nج: ما فيها شيء، هذه تُسمَّى: أجرة المحل.\nس: لكن العامل أتى من بلاده بناءً على عقدٍ بينه وبين الكفيل، على أن يُعطيه راتبًا؟!\nج: إذا تسامحوا لا بأس، فإذا تنازل العاملُ وصار في محلِّ تجارةٍ بأجرةٍ يُسلِّمها لكفيله، وهو الذي يعمل في المحلِّ أو يسكن في المحلِّ لا بأس.\nس: وإذا كان العاملُ يدفع الإيجارَ ويدفع أيضًا مئتي ريـالٍ للكفيل؟\nج: لا، ما يجوز أخذ شيءٍ على الكفالة، لكن يستأجر المحلَّ الذي فيه البيع والشّراء أو السكن، لا بأس.\nس: لكن النظام يمنع العاملَ أن يتَّجر بنفسه؟\nج: إذا كانت الدولةُ تمنع لا يعصي الدولة، ويُراجع الدوائر في هذا؛ لأنَّ هذه أمور تتعلق بمصلحة المسلمين، وعليه السمع والطاعة، ويمشي على التَّعاليم.","link":"https://binbaz.org.sa/fatwas/22349/حكم-تاجير-المحلات-للعاملين-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أخذ الأجرة عن المحلات المؤجرة للعمال.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":2978,"question":"الذي عنده أموال غير مشروعة هل يحق له أن يوزعها في الفقراء ويطبع فيها الكتب والأشرطة؟","title":"حكم التصرف في الأموال غير المشروعة","answer":"الجواب: نعم إذا كان عنده أموال ما هي طيبة: يصرفها في وجوه الخير، الصدقة على الفقراء، أو يطبع بها كتبًا؛ ما في بأس.\nس: تكون مقبولة؟\nالشيخ: لا، يعني تَبْرأ ذمته، براءة ذمته بركة، ويُؤجر على قصده الطيب إن شاء الله.","link":"https://binbaz.org.sa/fatwas/23135/حكم-التصرف-في-الاموال-غير-المشروعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تصريف الأموال غير المشروعة.mp3","categories":["الكسب المحرم"]},{"id":3126,"question":"رجل اتفق مع جماعة، هو محام في أحد البلاد، اتفق معهم على أنه يخلّص لهم حقوقًا عند الدولة فلمّا سعى وبذل مجهودًا وأنفق من جيبه أموالًا في هذا الأمر فإذا الأمر تيسّر وأخذوا حقوقهم، وكان اشترط عليهم أن يعطوه نسبة عشرين في المئة من هذه الحقوق ووافقوا على ذلك، فقال نظرت في الأمر فوجدت أن ربما لو ما بذلت هذا المجهود كانت وصلتهم الحقوق. فهل يجوز له أخذ هذه النسبة؟","title":"حكم أخذ نسبة مقابل تخليص الحقوق المالية","answer":"الجواب: إذا استأجروه يخلِّص حقوقهم ما فيه شيء.\nس: استأجروه على نسبة.\nالشيخ: إذا أنه يخلص حقوقهم ما يخالف.\nس: يقول إن الحقوق تخلصت بطريقة سهلة، كان من الممكن تتخلّص بدونه، لكن بعد ما بذل مجهودًا وأنفق أموالًا؟\nالشيخ: ما في بأس.","link":"https://binbaz.org.sa/fatwas/23287/حكم-اخذ-نسبة-مقابل-تخليص-الحقوق-المالية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أخذ نسبة معينة مقابل تخليص الحقوق.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":3442,"question":"الذين يَفِدُون بالعمال الآن من الكفار: يُعتبر هذا؟ يُوَفّى لهم بعهدهم، أم أنه لا بدّ أن يخرجوا؟","title":"حكم استقدام السفراء والعمال من الكفار","answer":"الجواب: ظاهر النص المنع، إلا مَنْ قَدِم لحاجة مؤقتة، مثل من يَقْدُم بميرة يبيعها، أو الرسول البريد الذي يأتي من الكفار، أو ما أشبه ذلك. أما هؤلاء الذين يأتون ويقيمون فيفسدون في الأرض، ويضرون المجتمع الإسلامي؛ فلا يجوز استقدامهم للعمل هنا في الجزيرة إلا للضرورة التي تدعو لها مصلحة المسلمين من إعداد سلاح، أو طب خاص، أو ما أشبه ذلك من الأشياء الفردية التي يحتاجها المسلمون، أما إطلاق هذا الأمر أن الناس حتى يستقدموا من شاؤوا فهذا لا يجوز، وقد صدر قرار من مجلس هيئة كبار العلماء من سنوات بهذا الأمر، ورُفع إلى ولي الأمر لمنع هذا التساهل، نسأل الله أن يعين على ذلك.\nس: صاحب المؤسسة يأثم يا شيخ إذا جاء بهم؟\nالشيخ: نعم ما يجوز له استقدام الكفرة، الواجب استقدام المسلمين، المسلمون هم في حاجة للنفع؛ فيختار من المسلمين من يظهر صلاحه، لا يأخذ من هب ودب، بعض المسلمين يدّعي الإسلام، وهو وثني يعبد غير الله؛ فينبغي للوكيل الذي يستقدم أو يتعاقد مع الناس ينبغي له أن يكون نبيهًا؛ حتى لا يختار ولا يتعاقد إلا مع من عرف بالإسلام الصحيح، ولا يتساهل في استقدام الكفرة، أو المخلّطين المعروفين بالوثنية، وهم يدّعون الإسلام.\nس: والسفراء، سفراء الدول؟\nالشيخ: السفير مستثنى؛ لأنه تدعو الحاجة إلى ذلك، مثل ما استُثني في وجوده بين الكفار، النبي ﷺ بعث أبا عبيدة سفيرًا في نجران بين النصارى.\nس: يعتبر كبيرة من كبائر الذنوب استقدام الكفرة؟\nالشيخ: على كُلٍّ معصية، أما كونه كبيرة فمحل نظر، لكنه لا يجوز؛ لأنه ما فيه وعيد، فيه وصية بإخراجهم، والكبيرة لها شروط.","link":"https://binbaz.org.sa/fatwas/23617/حكم-استقدام-السفراء-والعمال-من-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يوفى بعهد العمال من الكفار، وحكم استقدامهم، وحكم السفراء.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":3736,"question":"من دفع الرشوة لأخذ حقه؟","title":"حكم مَنْ يدفع الرشوة لأخذ حقه","answer":"الجواب: لا يدفع رشوة لا، يطالب بالطرق الشرعية، ولا داعي للرشوة.","link":"https://binbaz.org.sa/fatwas/23928/حكم-من-يدفع-الرشوة-لاخذ-حقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دفع الرشوة لأخذ الحقوق.mp3","categories":["الكسب المحرم"]},{"id":4048,"question":"هل يأثم إذا قال: تعال أقامرك؟","title":"ما حكم من قال \"تعال أقامرك\"؟","answer":"الجواب: نعم القمار الميسر يعني ما يجوز، ولهذا يشرع له التصدّق بدل هذا العمل السيئ الذي هو أكل الحرام، تعال أقامرك يعني: تعال نعمل القمار، نلعب القمار.\nس: ضابط القمار؟\nالشيخ: المخاطرة بالمال هذا القمار.","link":"https://binbaz.org.sa/fatwas/24285/ما-حكم-من-قال-تعال-اقامرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/القمار وضابطه.mp3","categories":["الكسب المحرم"]},{"id":4397,"question":"استأجرت محلًّا في أحد الأسواق التجارية، وبقيت في هذا المحل سنة، وكان دخل هذا المحل جيدًا، ويأتينا أحد من الناس ويقول: أعطيك نقل قدم مثلًا مائتي ألف ريال وأحل محلك، وصاحب الأسواق التجارية راضٍ؟","title":"حكم إيجار المرء ما لا يملكه","answer":"الجواب: تؤجره محلك بس بقية المدة التي لك بس، وإلا ما لك حق في الزيادة، لك تؤجر بقية المدة بقليل أو أكثر إذا كان مثلك أو أقل ضررًا، إذا كان عمله مثلك أو أقل ضررًا.\nس: وإذا كان صاحب الملك راضيًا؟\nج: ولو راضٍ، تؤجر شيء ما تملكه؟ لا، تؤجره الباقي بس.","link":"https://binbaz.org.sa/fatwas/24674/حكم-ايجار-المرء-ما-لا-يملكه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم إيجار ما لا يملكه.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":4875,"question":"إذا كان الراقي يفرغ نفسه في وقت معين، ثم يشترط على الذي يقرأ عليه مبلغًا معين ويضع لوحة تدل عليه؟","title":"حكم اشتراط الراقي مبلغًا ووضعه لوحة تدل عليه","answer":"ما أعلم فيه شيء، لكن إذا تسامح يكون أحسن، وإلا الصحابة شرطوا.\nس: لكنه يشترط؟\nج: لا بأس أن يشترط لكن ينبغي له أن يتسامح لا يشدد على الناس؛ لأن الناس بحاجة إلى من يرقيهم.\nس: لكن هل من السنة أن يضع لوحة ويدل على نفسه؟\nج: الأمر واسع إن شاء الله؛ لأن الناس قد يحتاجون إلى هذا.","link":"https://binbaz.org.sa/fatwas/25361/حكم-اشتراط-الراقي-مبلغا-ووضعه-لوحة-تدل-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اشتراط الراقي مبلغًا معين ووضعه لوحة تدل عليه.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":4876,"question":"ما وجه الخبث في كسب الحجام؟","title":"ما سبب وصف كسب الحجام بالخبيث؟","answer":"الله أعلم، لعلها من جهة إخراج الدم ومص الدم، فالدم أصله خبيث؛ لعله من أجل جهة إخراج الدم. وبعض أهل العلم قالوا: من باب التعاون بين المسلمين؛ فلا يأخذ أجرًا لأنها مسألة بسيطة فلا ينبغي أن يأخذ عليها أجرًا، مثل ما يعامل أخاه في الأشياء الخفيفة، ما تحتاج أجرًا، كونه يحمل له متاعه إلى السيارة أو على مطيته ما يحتاج يعطيه عليه أجرة، وهكذا الأمور البسيطة ما ينبغي فيها الأجر، من باب التعاون.","link":"https://binbaz.org.sa/fatwas/25363/ما-سبب-وصف-كسب-الحجام-بالخبيث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وجه الخبث في كسب الحجام.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":5041,"question":"بعضهم يأتي بكافرةٍ (خادمة)؟","title":"حكم استقدام الخادمة الكافرة؟","answer":"الجواب: لا، ما يجوز هذا، لا يجوز أن يأتي بكافرةٍ، يجب إبعادها، هذه الجزيرة العربية ما يكون فيها الكفار، النبي ﷺ أمر بإخراج الكفرة من هذه الجزيرة، لا من الرجال، ولا من النساء، والواجب عليه ردّها إلى بلادها.","link":"https://binbaz.org.sa/fatwas/29002/حكم-استقدام-الخادمة-الكافرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم استقدام الخادمة الكافرة؟.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":5164,"question":"سؤال عن استقدام بعض الناس لعُمَّال، ثم تركهم والأخذ عليهم في كلِّ شهر مبلغًا معينًا؟","title":"حكم استقدام العُمّال وأخذ مبالغ مالية عليهم","answer":"الجواب: أولًا: لا يجوز استقدام الكفرة، بل يجب الحذر من ذلك، أما المسلمون فلا بأس باستقدامهم على الطريقة التي رسمتها الدولة، فالدولة رسمت كيفية الاستقدام، فعلى المُستقدم أن يسير على ما بيَّنَتْه الدولةُ ورسمته، هذا هو الواجب على مَن يريد الاستقدام، حتى لا يضرَّ الناس باستقدام مَن لا ينبغي استقدامه.","link":"https://binbaz.org.sa/fatwas/30089/حكم-استقدام-العمال-واخذ-مبالغ-مالية-عليهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 113.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":5165,"question":"هذا يقول: السلام عليكم ورحمة الله وبركاته، ما حكم تأجير المحلات التّجارية على مَن يفتح محلًّا للحلاقة أو الخياطة النّسائية أو بيع أشرطة الفيديو أو أشرطة الغناء؟","title":"حكم تأجير المحلات التجارية لأمور محرَّمة","answer":"الجواب: لا تُؤجر المحلات لمَن يستأجرها لمعاصي الله، إنما تُؤجَّر لمَن يستأجرها للمُباح، فمَن استأجرها ليحلق لِحى الناس أو ليبيع آلات الملاهي أو ليبيع الخمر أو أي شيء من المعاصي فلا تُؤَجَّر له، لا يجوز في أي مكانٍ كان، ولو في أمريكا، ولو في أي مكانٍ، وهو مسلم، فلا يجوز له أن يُعين على معاصي الله، لا باستئجاره، ولا بغيره.","link":"https://binbaz.org.sa/fatwas/30090/حكم-تاجير-المحلات-التجارية-لامور-محرمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 114.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":5171,"question":"ما حكم الرشوة إذا كان حقِّي المعلوم أو تعويضي المُقدر لي لن يتم إلَّا عن طريقها؟","title":"حكم الرشوة لمن لا يمكنه تحصيل حقه إلا بها","answer":"الجواب: لا تجوز الرشوة؛ لأن هذا معناه إعانة على الباطل، وإعانة على تضييع الحقوق، وظلم الناس، يقول الرسولُ ﷺ: لعن الله الرَّاشي والمُرتشي، وفي روايةٍ: والرائش الواسطة بينهما أيضًا، فلا يجوز التعاون على الباطل والإثم، بل اطلب حقَّك من الطريق الشرعي، وإذا كان أحدٌ يقف في طريقك فارفع أمره، وافضحه على تساهله، ولا تُعنه على معاصي الله بالرشوة.","link":"https://binbaz.org.sa/fatwas/30098/حكم-الرشوة-لمن-لا-يمكنه-تحصيل-حقه-الا-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 123.mp3","categories":["الكسب المحرم"]},{"id":5181,"question":"رجلٌ يقول: أنا من الموظفين في مكة المكرمة، وعندما يأتي إليَّ الحجاج يُريدون أن أستأجر بيتًا، فأتفق أنا وصاحب البيت على أن يُؤجرهم مثلًا بألفين، ولي منه ثلاثمئة ريـال، فهل هذه رشوة؟","title":"حكم أخذ عمولة من مبالغ تأجير البيوت","answer":"الجواب: لا بدّ أن يُعلمهم إذا اتفق هو وإياه، فلا يجوز إلا أن يُعلمهم؛ لأن هذه من جنس الرشوة، لأنه يُخبرهم أنه بألفين وما هو بألفين، بل بألف وسبعمئة، فهذا ما يجوز، هذا من الرشوة، فإذا كان يريد الحلال فليقل لهم: إني اتفقتُ معه على أنها بألفين، وأن لي ثلاثمئة إذا كنتم تسمحون بذلك، وإلا فليس له إلا ألف وسبعمئة، وهو وافق على الثلاثمئة لي إن سمحتم بها، وإلا تركتها، أو ما أشبه ذلك من الكلام، يعني: لا بدّ أن يُبين لهم، وإلا فهو خيانة.","link":"https://binbaz.org.sa/fatwas/30117/حكم-اخذ-عمولة-من-مبالغ-تاجير-البيوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 143.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":5471,"question":"فِعْل الصِّدِّيق: الذي يأكل الحرام ويعلم بعدما أكل هل يقيء؟","title":"هل يلزم من علم أنه أكل حرامًا أن يقيئه؟","answer":"الجواب: إذا قاءه فحسن، وإلا فالظاهر ما هو بلازم؛ لأنه قد يشقّ عليه القيء، وهو معذور؛ ما دَرَى، لكن إذا قاءه تأسِّيًا بالصديق ، النبي عليه الصلاة والسلام قال: عليكم بسنتي وسنة الخلفاء.[1]","link":"https://binbaz.org.sa/fatwas/31350/هل-يلزم-من-علم-انه-اكل-حراما-ان-يقيىه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/reyath_alsalhin 007.mp3","categories":["الكسب المحرم"]},{"id":5488,"question":"الذين يُشجعون الكرة، ويقول بعضُهم: إذا فاز النادي الفلاني ذبيحتكم عليَّ؟","title":"ما حكم المغالبة على مالٍ في بعض الألعاب؟","answer":"الجواب: هذا ما يصلح، لا بالدراهم، ولا بالذبائح، ما يجوز هذا، هذا من الجعل المجهول، من القمار، ما يجوز، ولا يجوز لهم أن يأكلوا الذَّبيحة التي ذُبحت لهم؛ لأنَّ هذا من القمار، يقول الله جلَّ وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالْأَنْصَابُ وَالْأَزْلَامُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ [المائدة:90]، والميسر هو القمار، كونه يُغالب على مالٍ، غير السبق بالنَّصل والخفّ والحافر.[1]","link":"https://binbaz.org.sa/fatwas/31393/ما-حكم-المغالبة-على-مال-في-بعض-الالعاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 001.mp3","categories":["الكسب المحرم"]},{"id":6426,"question":"وآخر يسأل فيقول: أفيدكم أنني موظف والجهة التي أعمل بها توافق على انتداب أفراد لمدد مختلفة، دون أن يذهب الفرد المنتدب لأداء أي مهمة، والمسؤولون يعرفون ذلك، ويعتبرون بدل الانتداب هذا تشجيع للفرد، ومكافأة، وتشجيع له على ما يقوم به من عمل، و هل هذا المبلغ الذي آخذه عن بدل الانتداب حلال أم حرام؟","title":"حكم أخذ بدل انتداب دون الذهاب إلى ما انتدب إليه","answer":"الجواب: المعروف أن هذا لا يجوز، كونه يكتب له انتداباً، وهو ما انتدبه وهو في عمل ... ولا راح، المعروف أن هذا حيلة، وكذب، وغش للدولة، فيكون محرمًا؛ لأن هذا بغي بغير حق.  أما إذا كانت الدولة قد بلغها هذا، وأذنت للمسؤولين بأن يعملوا هذا لموظفيهم، وأن هذا عن شيء اتفقت عليه الدولة مع المديرين، أو مع الوزراء؛ فلا بأس بهذا؛ لأن الدولة ترى المصلحة، فإذا رأت أن تندب بعض الناس بالانتداب في الحقيقة، وأن يعطى المكافأة للمنتدب؛ تشجيعًا له على عمله كما يعطى المنتدب ما يعطى لأجل إعانته على عمله، ولا يجد في المقابلة تعباً، وفراقه لأهله، ونحو ذلك، إذا رأت الدولة ذلك لأجل تطييب نفوس المقيمين، ونشاطهم في العمل، وتشجيعهم في العمل هذا شيء إليها.  أما من جهة الموظف الذي فوقه يخدع الدولة، ويغش الدولة، ويعطيه شيئاً ما له حقيقة، فالأظهر من الأصول: أن هذا ربًا، ولا يجوز، محرم.","link":"https://binbaz.org.sa/fatwas/2143/حكم-اخذ-بدل-انتداب-دون-الذهاب-الى-ما-انتدب-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_792.mp3","categories":["الكسب المحرم","أحكام الموظفين"]},{"id":6515,"question":"إني أشك في مصدر أموال والدي، وأنه يمكن أن استخدم فيها الأموال الربوية والتزوير في الفواتير في البيع، فهل يجوز والحالة هذه أن آخذ من هذه الأموال، أو أن أتزوج من هذا المال، علمًا بأن والدي موافق بأن يعطيني من المال، وأنا موظف حكومي لا يكفي مالي للزواج؟","title":"حكم الأموال المختلطة من الحلال والحرام","answer":"الجواب: الأموال المختلطة عند أهل العلم جائز استعمالها، الأموال المختلطة التي قد يقع فيها حرام قد يقع فيها شيء مشبوه، فهذه جائزة، وغالب أموال الناس هكذا، من يسلم؟ وقد أخذ النبي ﷺ الجزية من اليهود، ومن النصارى، وأموالهم مختلطة، فيها الطيب، والخبيث.  أما إذا عرفت أن هذا المال بعينه ثمن دخان، أو ثمن خمر، أو مسروق، أو مغصوب؛ فلا تأخذه، ولا يحل لك، أما ما دامت مختلطة بالحلال، وغيره، ما تدري، ولا تميز، فالأصل الإباحة لا في بيت المال، ولا في أموال أبيك، ولا أخيك، ولا جيرانك، وإذا أغناك الله عن ذلك، ولا لك به حاجة، عندك شيء واضح، وكسب واضح، فالحمد لله استغن بالله.","link":"https://binbaz.org.sa/fatwas/2258/حكم-الاموال-المختلطة-من-الحلال-والحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_881.mp3","categories":["الكسب المحرم"]},{"id":6706,"question":"ما حكم من يأخذ على الأجنبي أجرًا مقدارها عشرة آلاف ريالًا مقابل أن يكون المحل باسمه؟","title":"حكم أخذ المال من الأجنبي مقابل فتح المحل باسمه","answer":"الجواب: ما أعرف لهذا أصلًا، هذا كذب، إذا ما كان له عمل، ولا هو شريك، ولا متشارك معه، وإنما هو مجرد يكذب، هذا لا أصل له، ولا يحل المال هذا، أما إذا كانت الشركة أنصافًا، أثلاثًا، أرباعًا، وتسمى باسمه .. في البيع، والشراء، وإيراد السلع، ونحو ذلك، أو القيام بالأعمال الأخرى من باب الشركة؛ فلا بأس. السؤال: يعني هم الخياطون الآن الذين يخيطون الملابس، المحل باسم واحد سعودي، لأن الأجانب ممنوعون ..، والأجانب هم الذين يدفعون لصاحب المحل، ويمارسون الخياطة، وهكذا النشاط..؟ الجواب: إذا كان شريكًا له؛ لا بأس، أما كذب، الحكومة منعت هذا الشيء، ويجعلونه كذبًا، وحيلة؛ لا يجوز، الكذب لا يجوز، إلا إذا كانت الدولة أمرتهم بأن يجعلوا باسم هذا .. الشخص هذا، وإن كان لهم ... إذا كان عن إذن من الدولة، في مصلحة رأتها الدولة؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/2583/حكم-اخذ-المال-من-الاجنبي-مقابل-فتح-المحل-باسمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1079.mp3","categories":["الكسب المحرم"]},{"id":7127,"question":"رجل كسب من السرقة والرشوة، ويعمل أعمالًا صالحات، مثل الصدقة والحج والعمرة والزكاة وكثير من أعمال الخير، هل هذه تذهب السيئات التي اكتسبها بسبب وزره؟","title":"حكم من يعمل الصالحات لكن كسبه حرام","answer":"الجواب:\n\nلا، يبقى عليه حق الناس الذين أخذ الرشوة في حقهم، والسرقة لا يكفي هذا، لا بد يرد على الناس حقوقهم، يقول ﷺ في الحديث الصحيح يقول لأصحابه: ما تعدون المفلس فيكم؟ قالوا : من لا درهم له ولا متاع، قال: لكن المفلس من يأتي يوم القيامة وقد شتم هذا، وضرب هذا، وأخذ مال هذا، وسفك دم هذا، وقذف هذا، فيعطى هذا من حسناته، ويعطى هذا من حسناته، فإن فنيت حسناته ولم يقض ما عليه؛ أخذ من سيئاته، فطرح عليه، ثم طرح في النار نعوذ بالله، لا بد أن يؤدي الحقوق للناس.","link":"https://binbaz.org.sa/fatwas/3159/حكم-من-يعمل-الصالحات-لكن-كسبه-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1517.mp3","categories":["الكسب المحرم"]},{"id":7723,"question":"السؤال أيضاً يقول: هل يجوز الضمان الاجتماعي لمن ليس في حاجة له؟","title":"حكم التسجيل في الضمان الاجتماعي لغير المحتاج","answer":"الجواب: الذي نعلم أن الحكومة وفقها الله جعلت الضمان الاجتماعي للفقير، فالذي لا تتوفر فيه الشروط ليس له أخذ الضمان وليس له أن يكذب، إنما يأخذ الضمان من كان من أهله لمن توافرت فيه الشروط المطلوبة، أما الذي يكذب ويزعم أنه فقير أو تزعم أنها ليست ذات زوج وهي ذات زوج أو ما أشبه ذلك فليس له أخذ ذلك.\nفالحاصل: أنه لا يجوز أخذ الضمان إلا للذي توافرت فيه الشروط التي وضعتها الدولة، هذا هو الواجب عليه، الواجب أن يتقي الله المؤمن وأن يحذر أخذ شيء لا يحل له، الله المستعان.","link":"https://binbaz.org.sa/fatwas/4922/حكم-التسجيل-في-الضمان-الاجتماعي-لغير-المحتاج ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_031/03109.mp3","categories":["الكسب المحرم"]},{"id":7725,"question":"سؤال مصلح السابع يقول: هل الرشوة عامة في كل شيء من الأموال، سواء كان نقوداً أم أرض أم غير ذلك، أفيدونا وفقكم الله؟","title":"حرمة الرشوة في كل شيء","answer":"الجواب: الرشوة لا تجوز، سواء كانت بالنقود أو بالأرض أو بغير ذلك، الرشوة محرمة، الرسول لعن الراشي والمرتشي، فلا يجوز أن يعطى الرشوة حتى يحيف له الأمير أو القاضي أو الشاهد أو نحو ذلك، الرشوة حرام، وعاقبتها وخيمة؛ وهي تفضي إلى الظلم الناس والعدوان عليهم في حقوقهم، فلا تجوز أبداً، سواء قدم مالاً من النقود أو مالاً من الأرض أو حيوان أو طعام، لا فرق في أنواع الرشوة. نعم. \nالمقدم: أحسنتم أثابكم الله.","link":"https://binbaz.org.sa/fatwas/4924/حرمة-الرشوة-في-كل-شيء ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_031/03111.mp3","categories":["الكسب المحرم"]},{"id":8794,"question":"السؤال الرابع والأخير: يقولون فيه الإخوة من العراق من محافظة أربيل: هل المال الذي يحصل عليه الشخص أو أي شيء آخر يحصل عليه الشخص مما يسمى باليانصيب الذي تقيمه بعض المصارف وبخاصة مصرف الرافدين في العراق، أو ما يحصل عليه الشخص من المسابقات الأخرى في البرامج وهي الحظ حلال أم حرام أفيدونا أفادكم الله؟","title":"حكم اليانصيب","answer":"الجواب: أما الأموال التي تحصل بطرق الميسر وهو القمار وهو المسمى اليانصيب عن طريق الحظ ونحو ذلك، هذه الأموال تؤخذ بغير الطريق الشرعي فلا تحل، قال الله جل وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالأَنصَابُ وَالأَزْلامُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ [المائدة:90]، والميسر: هو القمار، فما كان من طريق المغالبات في أي لعبة أو في أي عمل هذا هو الميسر وهو القمار، فلا يجوز للمسلم أن يتساهل بهذا الأمر؛ وإنما يحل له المال من طريقه الحلال، من طريق البيع والشراء الشرعي، من طريق الهبة الشرعية، من طريق اللفظ الشرعي، من طريق الأجرة الشرعية إلى غير ذلك طرق المال الحلال معروفة في الشرع المطهر.\nأما ما يتعلق بالقمار بأنواعه وهو الميسر، فلا يجوز للمسلم أن يتعاطاه، بل يجب عليه الحذر من ذلك، والكسب من هذا الطريق من طريق الميسر ومن طريق بيع الحرام كبيع الخمر والدخان أو ما أشبه ذلك هذا لا يحل، بل يجب على المسلم التحرز منه، يرجو ما عند الله ويخشى عقابه سبحانه وتعالى، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3]، والعبد إذا ترك شيئاً لله عوضه الله خيراً منه ، وهو القائل : وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]. نعم.","link":"https://binbaz.org.sa/fatwas/6952/حكم-اليانصيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_221/22105.mp3","categories":["الكسب المحرم"]},{"id":9802,"question":"هذه رسالة من المستمع سعيد محمد لافي الغامدي من بالجرشي يقول فيها: قال لي أحد الأشخاص: إن دفع مبلغ من المال رشوة لأحد الموظفين أو المسئولين الذين يحكمون في القضايا مثل القضاة أو رؤساء اللجان التي تقوم بالكشف على الأراضي ليس حرامًا في حالة إذا لم يثبت حق الشخص إلا بتلك الرشوة، وإذا لم يدفعها فإنه يضيع حقه، وإذا دفعها فإنه يحصل على حقه من غير ظلم لشخص آخر، فهل هذا الكلام صحيح، وأين نذهب من حديث الرسول ﷺ الذي قال فيه: لعن الله الراشي والمرتشي والرائش؟","title":"حكم دفع المرء الرشوة للحصول على حقه","answer":"الجواب: لا ريب أن دفع الرشوة إلى المسئولين من قضاة أو أمراء، أو لجان تفصل بين الناس لا شك أنه محرم، وأنه من كبائر الذنوب، والذي قال للسائل هذا الكلام أنه جائز فقد غلط وأخطأ على نفسه.\nلا يجوز دفع الرشوة ولا يجوز أخذها من دافعيها، بل يجب على المسئولين أن يتطهروا من ذلك وأن يبتعدوا عن ذلك وأن لا يعودوا أنفسهم، هذا المنكر العظيم وهذا الفساد الكبير، ومتى دخلت الرشوة على قوم أفسدتهم وضيعت حقوق الناس، وصار صاحب الرشوة هو الناجح ومن لا يرشي يذهب حقه، هذا من الظلم ومن البلاء العظيم والفساد الكبير، فلا يجوز أن يدفع إلى قاضٍ أو موظف أو أمير أو غير ذلك رشوة حتى يقدمك على غيرك أو حتى يحرم غيرك ويعطيك حقه، أو غير ذلك مما يكون فيه ظلم للناس وتعدي على الناس، أو تقديم بغير حق أو تأخير بغير حق.\nفالمقصود أن الرشوة من حيث هي محرمة ومنكر، وقد لعن الرسول ﷺ الراشي والمرتشي، فعليك يا عبد الله أن تحذر هذه الأقوال الساقطة، وأن تبتعد عما حرم الله عليك، وأن تطالب بحق إذا أخر حقك، تطالب بإعطائك حقك، أو بإحالة القضية إلى الجهات العليا، كالتمييز إذا رأيت من القاضي أنه حكم بشيء ترى أنك مظلوم فيه وأنه أخطأ، تطلب إحالة القضية إلى التمييز، أما أن تعطي رشوة أو تدفع رشوة لأحد حتى يساعد على الحكم بما يرضيك وبما يناسبك هذا منكر عظيم، لا مع القاضي ولا مع أتباع القاضي من كتبة أو غيرهم، كله منكر.\nوهكذا مع لجان الأراضي أو مع غيرهم ممن يفوض في أمر من الأمور الذي بين الناس لا يجوز أن يعطى رشوة ليقدمك أو ليعطك حق فلان، أو يزيدك على حقك، أو ما أشبه ذلك، بل يجب أن تخضع للأحكام الشرعية وللواقع الذي يقع، وتسأل من ولاة الأمور أن ينصفوك إذا رأيت أحدًا تعدى عليك، تطلب إنصافك وتبين وجه الظلم الذي حصل عليك، وولاة الأمور بحمد الله لن يتركوا حقك بل سوف ينصفونك إن شاء الله، ثم لو قدر أنك لم تنصف فما عند الله خير وأبقى، أما أن تقع في أمر لعن الله صاحبه فهذا خطر عظيم، ولا حول ولا قوة إلا بالله. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/7969/حكم-دفع-المرء-الرشوة-للحصول-على-حقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_197/19701.mp3","categories":["الكسب المحرم"]},{"id":9973,"question":"هذه رسالة وردتنا من السودان أيضاً من سائل رمز لاسمه بـ (أ. و. ك. هـ) من مديرية الخرطوم، يقول: والدي يعمل طباخ بالمستشفى بأجر محدود، ولكنه يأخذ من المواد التموينية من المستشفى كالزيت وغيرها فوق أجره المعلوم، وقدمنا له النصيحة في ذلك ولكنه رفض بحجة أن هذه المواد التموينية متوفرة ولا حرج في الأخذ منها، ثم توقفت الأسرة عن الأكل من هذه المواد وأخذ أخي الأكبر ينفق على الأسرة، مع أنه واقع في لعب الميسر وقدمنا له النصيحة هو الآخر، ولكنه رفض وبعد ذلك أخذت الوالدة تعمل في البيع والشراء لتوفر لنا لقمة العيش الكريمة،  هل هناك ضرورة شرعية في أن نأخذ من هذه المواد المجلوبة بغير حق، أم نأخذ من مال أخي المختلط بلعب الميسر، أم نبقى على نفقة الوالدة التي ضاق بها الحال؟ أفيدونا أفادكم الله.","title":"حكم النفقة من مال لم يؤذن له فيه أو من الميسر","answer":"الجواب: الواجب على أبيك أن يتقي الله وأن يرضى بالأجر الذي شرط له، وأن يترك الأخذ من المواد التي لديه، التي اؤتمن عليها من المستشفى، فليس له أن يأخذ منها شيئًا إلا بإذن المرجع، فلا يأخذ من اللحوم، ولا من الزيت، ولا من غير هذا إلا بإذن، وهكذا أخوك عليه أن يتقي الله ويدع الميسر وهو القمار وهو محرم عظيم من كبائر الذنوب، فعليكم أن تنصحوا الوالد والأخ، وهكذا إخوانكم الطيبون ينصحون معكم الوالد والأخ، تعاونوا على النصيحة، فالدين النصيحة، وهكذا المسلمون يتناصحون فإن قبل والدك وقبل أخوك فالحمد لله وإلا فقد أديتم ما عليكم من النصيحة، ولا مانع أن تأكلوا مما تأتي به الوالدة من كسبها الطيب، وهي مأجورة ومشكورة، وإذا أعطاكم أخوكم شيئًا لا تعلمون أنه من القمار فلا شيء، أو أعطاكم الوالد شيئًا من غير المواد الزائدة التي يأخذها فلا بأس، أما إذا علمتم أن هذا الذي أعطاكم الأخ من القمار فلا تأخذوه، أو علمتم أن الذي أعطاكم الوالد من نفس الخيانة فلا تأخذوه، ونسأل الله للجميع الهداية. نعم.\nالمقدم: بارك الله فيكم وشكر لكم.","link":"https://binbaz.org.sa/fatwas/8132/حكم-النفقة-من-مال-لم-يوذن-له-فيه-او-من-الميسر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_274/27409.mp3","categories":["الكسب المحرم"]},{"id":10352,"question":"تقول: إن لها والد ربح مالاً كثيراً من اليانصيب فهل لهم أن يأكلوا من ذلك المال؟","title":"حكم الأكل من أموال اليانصيب","answer":"الجواب: الربح من اليانصيب هذا ليس من المال الشرعي بل هو من القمار من الميسر، وجميع الأموال التي تحصل من الميسر محرمة، والله جل وعلا يقول سبحانه في كتابه العظيم: إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالأَنصَابُ وَالأَزْلامُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ [المائدة:90]، والميسر: هو القمار، واليانصيب: هو القمار، فهذه الأموال التي حصل عليها الوالد من القمار يجب أن تصرف في وجوه البر وأعمال الخير، كإصلاح الطرقات ودورات المياه والصدقة على الفقراء والمحاويج، أما أنه يأكلها فلا يأكلها ولا يأكلها ورثته وهم يعلمون أنها من هذا الطريق.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8530/حكم-الاكل-من-اموال-اليانصيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_316/31611.mp3","categories":["الكسب المحرم"]},{"id":12186,"question":"آخر سؤال لأختنا في هذه الحلقة يقول: يجري في بعض المعارض التجارية، أو معارض الألعاب السياحية سحب على أرقام بطاقات الدخول، حيث لمن أراد دخول المعرض يدفع ثمن بطاقة الدخول، ويدخل، ويشاهد ما في المعرض، أو يشارك في بعض الألعاب، ومن فترة لأخرى يجري السحب على أرقام بطاقات الدخول، وتوزع جوائز، هل يجوز أخذ هذه الجوائز، علمًا بأن الداخل للمعرض لم يخسر شيئًا، بل شاهد ما في المعرض، أو شارك ببعض الألعاب مقابل ثمن بطاقة الدخول؟","title":"حكم المسابقات التي تقام على سحب أرقام بطاقات","answer":"الجواب:  هذا من القمار، ما يجوز، هذا قمار وميسر لا يجوز، وأكل للأموال بالباطل، نسأل الله العافية، قد يخسر ولا يستفيد شيئًا، نعم، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10372/حكم-المسابقات-التي-تقام-على-سحب-ارقام-بطاقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_443/44313.mp3","categories":["الكسب المحرم"]},{"id":12235,"question":"يقول في آخر سؤال له: لي أخ يعمل في مجال الدعاية لشركة أدوية، ويتسلم بعض الأدوية لتوزيعها كعينات، فهل يحل له إعطاء ذويه منها، أم يحرم ذلك؟","title":"حكم تصرف موزع الشركة في العينات التي يوزعها للعملاء","answer":"الجواب: ليس له أن يعطي ذويه إلا بإذن من الشركة، إذا سمحت أن يعطي أحدًا يعطي، فليس له أن يعطي أحدًا لا قراباته، ولا غيرهم إلا بإذن الشركة، إذا كان إنما مهمته يري الزبون، يطلعهم عليه حتى يعرفوا الدواء، لكن ليس له أن يعطي أحدًا من الناس إلا بإذن الشركة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10423/حكم-تصرف-موزع-الشركة-في-العينات-التي-يوزعها-للعملاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_447/44711.mp3","categories":["الكسب المحرم","أحكام الموظفين"]},{"id":15092,"question":"يقول: ما حكم من يدفع مبلغًا ما، لشخص لقضاء مصلحة من حقه شرعًا قضاؤها مجانًا، مع العلم أنه من غير هذا المبلغ لا يمكن أن يقضيها، ويمكن أن ينتظر أيامًا وشهورًا، ولا يوجد عنده الوقت للانتظار؟","title":"حكم من دفع مالًا لمن أنجز له معاملة","answer":"الجواب: هذا السؤال فيه إجمال، فإن كان هذا العمل يتضمن ظلم الآخرين؛ وذلك بالرشوة فلا يجوز، لأنه إذا كانت الرشوة إذا كان يعطيه رشوة حتى يقدمه على غيره، وحتى يظلم غيره، فالرشوة حرام منكر. أما إذا كان وكيلًا له، يعطيه مالًا؛ ليسعى في إخراج معاملة له، أو في خصومة له، فلا حرج في ذلك؛ لتعبه عن وكالته. أما أنه يعطي الموظف رشوة حتى يعطيه غير حقه، أو حتى يقدمه على من هو أولى منه، هذا لا يجوز. فالمقصود: أن هذا السؤال فيه إجمال، فإن كان دفع المال يضر أحدًا، أو يظلم أحدًا، أو يعطل أحدًا عن حقه بسبب أخذه المال، يظلم الناس من أجل هذا المال الذي أخذه من الشخص، حتى يقدمه عليهم، فلا يجوز، هذه الرشوة المحرمة.  أما إذا كان المال يعطيه لمساعدة من غير تعلق بالوظيفة، أو لكونه وكيلًا يتعب عنه، ويراجع المحكمة، ويراجع الناس في إنهاء المهمة التي لهذا الشخص فلا بأس. فالواجب على السائل أن يوضح الأمر توضيحًا بين؛ حتى تكون الإجابة على ضوء ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13586/حكم-من-دفع-مالا-لمن-انجز-له-معاملة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_494/49403.mp3","categories":["الكسب المحرم"]},{"id":15429,"question":"هذا سائل من جمهورية مصر العربية، يقول: أنا شخص تبت إلى الله توبة نصوح، وقد اكتسبت جمعًا من المال من طريق غير شرعي، ويستحيل علي أن أرد هذا المال لأهله؛ لأنهم قد ماتوا، وإذا تصدقت به، فما هو موقف المتصدق عليه إذا كان يعلم بأن هذا المال حرام؟ وهل أخبره بذلك؟ وهل يجوز أن أتصدق بهذا المال على أهلي؟","title":"ما الواجب على من أخذ مالًا حرامًا ثم تاب؟","answer":"الجواب: الواجب عليك أن ترده للورثة، تعطية ورثة الميت، إذا كان له ورثة، تعطيهم إياه، أما إذا كان ما له ورثة، أو لا تعرفهم، ولا تعرف عنوانهم، تتصدق به على الفقراء، ولا تخبرهم، تتصدق به على الفقراء ولا تخبرهم أنه كذا ولا كذا، وتبرأ الذمة مع التوبة، والحمد لله. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13942/ما-الواجب-على-من-اخذ-مالا-حراما-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_568/56802.mp3","categories":["الكسب المحرم"]},{"id":16341,"question":"يرجو من سماحتكم أن تتفضلوا بمعالجة موضوع الرشوة، ذلك أنه منتشر في قضايا كثيرة، وفي بلده بالذات -ويسمي بلده سماحة الشيخ- جزاكم الله خيرًا.","title":"نصيحة حول ظاهرة الرشوة","answer":"الجواب: لا بأس، نرجو ذلك، نكتب في هذا -إن شاء الله- وقد كتب فيه، لكن نكتب فيه -إن شاء الله- مرة بعد مرة، نسأل الله أن يصلح أحوال المسلمين. والرشوة لا شك أنها من الكبائر، والنبي  يقول: من غشنا فليس منا لعن الراشي، والمرتشي، والرائش الراشي: الباذل، والمرتشي: القابل، والرائش: الواسطة بينهما. فالواجب الحذر منها، وهي دفع المال لمن يعطيك غير حقك، أو يقدمك على مستحق قبلك، هذه رشوة، وبتعطيه حتى يقدمك على غيرك، أو يعطيك غير حقك بغير حق، خيانة، هذا لا يجوز، وهو من الرشوة، والفاعل ملعون، هذا وهذا، فالواجب الحذر من ذلك. بل يجب على المسلم أن يحذر الرشوة، لا تدفع للموظف مالًا حتى يقدمك على ناس غيرك هم أحق بالتقديم، أو يعطيك مال غيرك، أو يعطيك ما لا تستحق، أو يجعلك في وظيفة لا تستحقها، غيرك أولى بها، هذا كله من الرشوة. والمقصود: أنك تدفع مالًا لشيء ليس بحق لك، تدفعه ليخون آخذ المال حتى يحابيك، هذا منكر، ولا يجوز، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15035/نصيحة-حول-ظاهرة-الرشوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_714/nour_71404.mp3","categories":["الكسب المحرم"]},{"id":16562,"question":"ما جزاء الراشي، والمرتشي؟","title":"عقوبة الراشي والمرتشي","answer":"الجواب: الراشي، والمرتشي قد أتيا كبيرة عظيمة، في الحديث الصحيح أن الرسول ﷺ: لعن الراشي والمرتشي. والرشوة: بذل المال لمن يعمل لك ما يخالف الأمر الشرعي، ما يخل بالأمانة، والقابل للرشوة هو الذي يفعل ما حرم الله عليه من أجل الرشوة، كأن يعطيك ما ليس بحق لك، أو يقدمك على من هو أولى منك من أجل الرشوة، أو يخبر بأنك مواظب على العمل، وأنت لست مواظبًا على العمل من أجل الرشوة، ونحو ذلك، فالمال الذي يبذل في خلاف الحق آخذه ظالم، وباذله كذلك، ويعتبران متعاونين على الإثم والعدوان. نسأل الله العافية.  المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15302/عقوبة-الراشي-والمرتشي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_816/nour_81614.mp3","categories":["الأخلاق المذمومة","الكسب المحرم"]},{"id":16970,"question":"يسأل سماحتكم عن الميسر المذكور في القرآن الكريم؟","title":"معنى الميسر وحكمه","answer":"الجواب: يقول الله -جل وعلا- في كتابه العظيم: يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالأَنصَابُ وَالأَزْلامُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ [المائدة:90] الميسر القمار، وهو اللعب بالمال ... يتسابقون بالأقدام، أو يقولون هذا كذا، وهذا كذا، ولك إن غلبتني كذا من المال، يسمى ميسرًا، ويسمى قمارًا، أو يتراهنون على شيء بأن يقول: إن غلبتني في المصارعة، أو غلبتني في السبق إلى كذا على الأقدام، أو على الحمير والبغال فلك كذا، هذا كله قمار، وميسر. أما إذا كان بالإبل، أو بالخيل، أو بالرمي فهذا مشروع، لا بأس به، هذه المسابقة بالإبل، أو بالخيل، أو بالرمي لا بأس أن يأخذ عليها العوض؛ لقوله ﷺ: لا سبق إلا في نصل، أو خف، أو حافر فـالنصل الرمي، والخف الإبل، والحافر الخيل، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15755/معنى-الميسر-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_720/nour_72003.mp3","categories":["الكسب المحرم"]},{"id":17540,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين هو محمد عبد الله عبد الله ، أخونا يقول: شخص يعمل في مكان تعاوني وكان جاهلًا، وأخذ من هذا المكان مالًا بطريقة غير شرعية، وأعطى هذا المال والده ولم يعلمه في تلك الآونة أنه أخذه بطريقة غير مشروعة، الآن يريد أن يعيد هذا المال لأصحابه، علمًا بأن ذلك المكان التعاوني مقفل الآن وأصحابه تخلو عنه، فماذا يفعل؟ جزاكم الله خيرًا.","title":"حكم من أخذ مالا وأراد إرجاعه فلم يجد صاحبه","answer":"الجواب: أولًا: عليه التوبة إلى الله من ذلك، عليه التوبة النصوح من هذا العمل السيئ وذلك بالندم على ما مضى منه والعزم الصادق ألا يعود فيه والحرص على التخلص من هذا المال، فإن كان يعرف أهل المحل يعطيهم إياه، إذا استطاع ذلك، فإن لم يستطع ذلك يتصدق به عنهم، يدفعه لبعض الفقراء بالصدقة عنهم بالنية، أما إن استطاع إيصاله إليهم فإنه يرسله إليهم على حسب حصصهم، وإن كان لهم رئيس يرجعون إليه أرسله إلى رئيسهم حتى يوزعه بينهم.\nالمقصود أنه يحرص على إيصاله لأهله بالطريقة التي تمكنه، الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، فإن عجز ولم يستطع تصدق به على بعض الفقراء بالنية عنهم عن أصحابه، والله ينفعهم بهذا . نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16468/حكم-من-اخذ-مالا-واراد-ارجاعه-فلم-يجد-صاحبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_838/nour_83802.mp3","categories":["الكسب المحرم"]},{"id":18488,"question":"رجل جمع مالًا من حرام، وبعد أن صار غنيًا يقول: بدأ في العبادة، فما الحكم الشرعي في هذا الدين في ماله؟","title":"حكم من تاب بعد أن جمع مالًا من حرام","answer":"الجواب: يتصدق عما دخله من حرام إذا كان يعرف ذلك، يتصدق بمقابل ما دخله من الحرام، أو يجتهد إذا كان لا يحفظ، يجتهد ويتصدق بما يظنه يقابل ما دخل عليه من الحرام، ويتوب إلى الله، ويقلع، ويندم، ويسأل ربه المغفرة، والحمد لله فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16]. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17579/حكم-من-تاب-بعد-ان-جمع-مالا-من-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_785/nour_78521.mp3","categories":["الكسب المحرم"]},{"id":18763,"question":"من تونس السائل الذي رمز لاسمه بـ (ع. ج) يقول: أستفسر عن الحكم الشرعي في التعامل بالرشوة في هذا العصر، كيف السبيل للعلاج من هذا المرض العضال؟","title":"حرمة الرشوة في الإسلام","answer":"الجواب: الرشوة محرمة، والواجب الحذر منها، «الرسول ﷺ لعن الراشي والمرتشي» فإذا رشا إنسانًا ليفعل معه ما حرم الله عليه ما يجوز، كأن يعطي موظفًا رشوة حتى يقدمه على غيره، وحتى يعطيه ما لا يحل له؛ هذا لا يجوز، المقصود: الرشوة أن يبذل مالًا ليأخذ ما لا يحل له، أو يعطى ما لا يحل له، فلا يجوز لا للفاعل ولا الآخذ، لا للدافع ولا للآخذ؛ لأنه تعاون على الإثم والعدوان، والله يقول سبحانه: وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ[المائدة:2]، فكونه يعطي رشوة لأي شخص حتى يفعل معه ما لا يجوز هذا حرام على الآخذ والمعطي، وعلى المتوسط بينهما أيضًا؛ ولهذا في الحديث الصحيح «الرسول ﷺ لعن الراشي والمرتشي، وفي رواية: والرائش» يعني: الواسطة بينهما، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17893/حرمة-الرشوة-في-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_790/nour_79019.mp3","categories":["الكسب المحرم"]},{"id":19133,"question":"يسأل سؤال يقول: هل الرشوة حرام؟","title":"حكم الرشوة","answer":"الجواب: نعم، الرشوة كبيرة من الكبائر، والرسول ﷺ لعن الراشي والمرتشي؛ ولأنها تجر إلى الباطل، والظلم، وأكل الحرام، وخيانة المرشي؛ فلا يجوز تعاطيها بالكلية، وهي دفع مال لمن يخون لك، ويعطيك غير حقك، أو يقدمك على غيرك من المستحقين من أجل رشوة، هذه الرشوة تعطيها الموظف حتى يعطيك غير حقك، وحتى يعمل لك ما لا يجوز، أو ما لا يقره النظام الذي لديه والعمل الذي لديه، والتعليمات التي لديه، وإنما حمله على ذلك ما دفعته له من المال، هذه يقال لها: الرشوة، فهي حرام عليك، وعليه جميعًا، وفي الحديث اللعن للراشي والمرتشي جميعًا، وهكذا إذا أعطيته إياها ليقدمك على ناس هم أحق منك بهذا الشيء الذي طلبت ولكن قدمك عليهم من أجل الرشوة هذا أيضًا من المنكر، نسأل الله السلامة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18338/حكم-الرشوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_798/nour_79804.mp3","categories":["الكسب المحرم"]}]
